<script setup>
import { ref } from 'vue'
import {isStaticDemo} from '../runtime.js'
import { account, signIn, restoreAccount } from '../domain/account.js'
const emit=defineEmits(['success'])
let remembered='';try{remembered=localStorage.getItem('ebike-last-admin-account')||''}catch{}
const username=ref(remembered||'admin'),password=ref(''),remember=ref(!!remembered),show=ref(false),busy=ref(false),error=ref('')
async function login(){error.value='';busy.value=true;try{await signIn(username.value.trim(),password.value);try{if(remember.value)localStorage.setItem('ebike-last-admin-account',username.value.trim());else localStorage.removeItem('ebike-last-admin-account')}catch{}password.value='';emit('success')}catch(e){error.value=e.message;password.value=''}finally{busy.value=false}}
</script>
<template><main class="auth-shell"><div class="auth-brand"><span class="auth-logo">ϟ</span><span>非机动车充电管理平台</span></div><section class="login-card"><div class="login-accent"></div><header><h1>{{isStaticDemo?'校园充电公开演示':'管理员登录'}}</h1><p>{{isStaticDemo?'浏览器本地数据 · 无真实支付与设备控制':'登录后管理站点、设备与独立插座'}}</p></header><p v-if="account.loginMessage" class="login-info" role="status">{{account.loginMessage}}</p><p v-if="error||account.error" class="form-error" role="alert">{{error||account.error}}</p><div v-if="isStaticDemo" class="static-demo-entry"><p class="form-hint">无需账号密码。演示数据仅保存在当前浏览器。</p><button class="login-submit" :disabled="busy" @click="login">进入公开演示</button></div><form v-else @submit.prevent="login"><label>账号<input v-model="username" autocomplete="username" required maxlength="64" placeholder="请输入管理员账号"/></label><label>密码<div class="password-input"><input v-model="password" :type="show?'text':'password'" autocomplete="current-password" required maxlength="64" placeholder="请输入密码"/><button type="button" @click="show=!show" :aria-label="show?'隐藏密码':'显示密码'">{{show?'隐藏':'显示'}}</button></div></label><label class="remember-account"><input v-model="remember" type="checkbox"/> 记住账号 <span>不保存密码</span></label><button class="login-submit" :disabled="busy" type="submit">{{busy?'正在登录…':'登 录'}}</button></form><button v-if="account.error" class="text-button reconnect-button" @click="restoreAccount">重试连接账号服务</button><div v-if="!isStaticDemo" class="login-help"><strong>本机首次初始化</strong><p>账号 <code>admin</code> · 初始密码 <code>Admin@123456</code></p><small>仅新建账号时生效，已修改的密码不会被覆盖。</small></div></section><footer class="login-footer">校园 · 住宅小区 · 园区<br/>{{isStaticDemo?'公开静态演示 · 数据仅保存在当前浏览器':'账号由本机 Spring Boot 服务校验；充电设备与业务数据仍为软件模拟。'}}</footer></main></template>
